from PIL import Image
import numpy as np
im = np.array(Image.open('mol_0064.png').convert('L'))
dark = im < 128
def width_at(x,y,r=6):
    # measure horizontal run of dark around (x,y)
    xs=[]
    for dx in range(-r,r+1):
        if 0<=x+dx<dark.shape[1] and dark[y,x+dx]: xs.append(dx)
    return (min(xs),max(xs),len(xs)) if xs else None
print('O-C vertical bond widths (horizontal run):')
for y in range(146,216,6):
    print(y, width_at(197,y))
print('Cq-CH2 bond widths (vertical run):')
def vwidth(x,y,r=6):
    ys=[]
    for dy in range(-r,r+1):
        if 0<=y+dy<dark.shape[0] and dark[y+dy,x]: ys.append(dy)
    return (min(ys),max(ys),len(ys)) if ys else None
for x in range(155,196,5):
    print(x, vwidth(x,213))
"
